const text=(value,max=200)=>{if(typeof value!=='string'||value.trim().length>max)throw new Error('Enter valid operation details.');return value.trim()}
const defaultHousekeepingTasks=['Remove used linen','Make the bed','Clean the bathroom','Replenish guest supplies','Empty bins','Inspect the room']
const iso=value=>typeof value==='string'&&Number.isFinite(Date.parse(value))
const date=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const parsed=new Date(`${value}T00:00:00.000Z`);return Number.isFinite(parsed.getTime())&&parsed.toISOString().slice(0,10)===value}
const parsePromotionLines=(raw)=>String(raw||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const [code,percentOff,limit,ticketTypeId='']=line.split('|').map(value=>value.trim());return{code:(code||'').toUpperCase(),percentOff:Number(percentOff),limit:Number(limit),...(ticketTypeId?{ticketTypeId}:{})}})
const parsePackageLines=(raw,menuItems=[])=>String(raw||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map((line,index)=>{const [name,description,minimumSpend,limit,contents='']=line.split('|').map(value=>value.trim()),items=contents?contents.split(';').map(part=>{const split=part.lastIndexOf('='),itemName=part.slice(0,split).trim(),quantity=Number(part.slice(split+1).trim()),item=menuItems.find(row=>row.name?.toLocaleLowerCase()===itemName.toLocaleLowerCase()&&row.available&&row.type==='stock'&&row.productId);if(split<1||!item||!Number.isInteger(quantity)||quantity<1||quantity>999)throw new Error(`Choose valid stocked menu items for package ${name||index+1}.`);return{menuItemId:item.id,productId:item.productId,name:item.name,quantity}}):[];return{id:`bottle_${index+1}`,name:name||'',description:description||'',minimumSpend:Number(minimumSpend),limit:Number(limit),...(items.length?{items}:{})}})
export function hotelRateBreakdown(room,checkIn,checkOut){
  const nights=(Date.parse(`${checkOut}T00:00:00Z`)-Date.parse(`${checkIn}T00:00:00Z`))/86400000
  if(!date(checkIn)||!date(checkOut)||!Number.isInteger(nights)||nights<1||nights>366)throw new Error('Choose valid stay dates for no more than 366 nights.')
  const byRate=new Map()
  for(let offset=0;offset<nights;offset++){
    const day=new Date(Date.parse(`${checkIn}T00:00:00Z`)+offset*86400000).toISOString().slice(0,10)
    const period=(room.ratePeriods||[]).find(row=>row.startDate<=day&&day<=row.endDate)
    const rate=Number(period?.nightlyRate??room.nightlyRate)
    byRate.set(rate,(byRate.get(rate)||0)+1)
  }
  return [...byRate].map(([nightlyRate,count])=>({nightlyRate,nights:count}))
}
